ids=json.load(open("/home/hatch/workspace/divination/benchmark/phase3/runs/round47/batches.json"))["B18"]
assert len(ids)==20, len(ids)
written=0
for cid in ids:
    assert cid in P, cid
    rec={"case_id":cid,"prediction_text":P[cid]["prediction_text"],"basis":P[cid]["basis"],"confidence":P[cid]["confidence"],"trigger":T}
    with open(os.path.join(BASE,cid+".json"),"w",encoding="utf-8") as f:
        json.dump(rec,f,ensure_ascii=False,indent=1)
    written+=1
# verify by exact id list only
cnt=0
for cid in ids:
    d=json.load(open(os.path.join(BASE,cid+".json"),encoding="utf-8"))
    assert d["case_id"]==cid and set(d["trigger"].keys())=={"changed_main","reserve_used","disputed","reason"}
    cnt+=1
assert cnt==len(ids)==written==20
print("written",written,"verified",cnt)
print("trigger counts: changed_main",sum(1 for c in ids if P[c]), "all false by construction")
